sys_script.script:
(function executeRule(current, previous /*null when async*/ ) {
    try {
        if (current.trade_task_type == 'Maker') {
           // gs.info('AMENDCONF --> BR Triggered - Clear fields for Maker - Task -' + current.number);
            var tradeDisplayValue = current.trade_id.getDisplayValue();
            //gs.info('AMENDCONF BR Triggered - Clear fields for Maker trade id - ' + tradeDisplayValue);
            var gr = new GlideRecord("x_hsb11_mss_c_proc_mss_custody_task");
            gr.addEncodedQuery('state=3^trade_task_type=GHSS Handler - Amend^outcome=Amend and CONF^trade_idSTARTSWITH' + tradeDisplayValue);
            gr.query();
            if (gr.next()) {
                gs.info('AMENDCONF BR Triggered - Clear fields for Maker Found Valid Task - ');
                var baseQuery = 'trade_idSTARTSWITH' + tradeDisplayValue;
                var query1 = baseQuery + '^trade_task_template_idSTARTSWITHCUSTODYTTMP00001';
                var query2 = baseQuery + '^trade_task_template_idSTARTSWITHCUSTODYTTMP00026';

                var newMaker = new GlideRecord("x_hsb11_mss_c_proc_mss_custody_task");
                newMaker.addEncodedQuery(query1 + '^NQ' + query2);
                newMaker.orderByDesc('sys_created_on');
                newMaker.query();
                if (newMaker.next()) {
                    newMaker.setValue('trade_id', '');
                    newMaker.setValue('trade_case_id', '');
                    newMaker.setValue('bulk_id', '');
                    newMaker.update();
                   // gs.info('AMENDCONF BR Triggered Cleared fields for Maker');
                }
            }
        } else {
            //  if a successful confirm widget exists
            var taskGr = new GlideRecord('x_hsb11_mss_c_proc_mss_custody_task');
            taskGr.addEncodedQuery('trade_task_type=GHSS Handler - Confirm^bulk_id=' + current.bulk_id + '^state=4');
            taskGr.query();
            while (taskGr.next()) {
                taskGr.setValue('trade_id', '');
                taskGr.setValue('trade_case_id', '');
                taskGr.setValue('bulk_id', '');
                taskGr.update();
            }
        }
    } catch (ex) {
        gs.error('AMENDCONF BR Triggered Error in Maker Task update BR: ' + ex.message);
    }
})(current, previous);
